"""matplotlib.backends.qt_compat — Qt5/6 binding shim.

Real matplotlib uses this to abstract over PyQt5/PyQt6/PySide. The
shim has no Qt backend, so we expose the constants as None and let
imports succeed for the few users that probe this module."""

QT_API = None
QT_API_PYQT5 = 'PyQt5'
QT_API_PYQT6 = 'PyQt6'
QT_API_PYSIDE2 = 'PySide2'
QT_API_PYSIDE6 = 'PySide6'

is_pyqt5 = False


QT_API_ENV = None
